from pathlib import Path
from html import escape

ROOT = Path(__file__).parent
PAGES = ROOT / 'pages'
DOCS = ROOT / 'docs'
HERO = 'assets/img/void-orbit.svg'
ECOSYSTEM = 'assets/img/void-signal.svg'
CASE = 'assets/img/void-fragment.svg'
CULTURE = 'assets/img/void-portrait.webp'
URBAN = 'assets/img/void-urban.webp'

def shell(title, description, body, active=''):
    return f'''<!doctype html>
<html lang="pt-BR">
<head>
  <meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
  <title>{title} — Black Void</title><meta name="description" content="{description}">
  <link rel="icon" href="assets/img/logo.png">
  <link rel="stylesheet" href="assets/css/style.css">
</head>
<body>
  <div id="loader"><img class="ldr-mark" src="assets/img/logo.png" alt=""><div class="ldr-word">BLACK VOID / ARCHIVE</div><div class="ldr-bar"><i></i></div></div>
  <div data-include="../components/menu-superior.html"></div>
  <main>{body}</main>
  <footer><div data-include="../components/menu.html"></div></footer>
  <script src="../components/include.js"></script><script src="assets/js/main.js"></script>
</body></html>'''

def root_shell(title, description, body):
    return f'''<!doctype html>
<html lang="pt-BR">
<head>
  <meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
  <title>{title} — Black Void</title><meta name="description" content="{description}">
  <link rel="icon" href="pages/assets/img/logo.png">
  <link rel="stylesheet" href="pages/assets/css/style.css">
</head>
<body>
  <div id="loader"><img class="ldr-mark" src="pages/assets/img/logo.png" alt=""><div class="ldr-word">BLACK VOID / ARCHIVE</div><div class="ldr-bar"><i></i></div></div>
  <div data-include="components/menu-superior.html"></div>
  <main>{body}</main>
  <footer><div data-include="components/menu.html"></div></footer>
  <script src="components/include.js"></script><script src="pages/assets/js/main.js"></script><script src="agent/kira.js"></script>
</body></html>'''

def hero(kicker, title, deck, chapter='01'):
    return f'''<section class="page-hero"><div class="wrap"><div class="crumb">BLACK VOID <i>/</i> {chapter}</div><span class="eyebrow reveal">{kicker}</span><h1 class="h-xl reveal" style="margin-top:22px">{title}</h1><p class="lead reveal" style="margin-top:30px">{deck}</p></div></section>'''

def cta(label='Abrir uma conversa'):
    return f'''<section class="cta-block"><div class="wrap"><span class="eyebrow">Próximo capítulo</span><h2 class="reveal" style="margin-top:18px">A complexidade<br>pode <em style="color:var(--void-red);font-style:normal">ceder.</em></h2><a class="btn" href="contato.html">{label} <span aria-hidden="true">↗</span></a></div></section>'''

def chapters(items):
    def tag_markup(values):
        return '<div style="margin-top:20px">' + ''.join(f'<span class="pill">{escape(value)}</span>' for value in values) + '</div>' if values else ''
    return '<div class="chapter-list">' + ''.join(f'''<article class="chapter reveal"><span class="chapter-index">{i:02d} / {label.upper()}</span><div><h3>{title}</h3><p>{desc}</p>{tag_markup(tag_values)}</div></article>''' for i, (label, title, desc, tag_values) in enumerate(items, 1)) + '</div>'

def tags(items):
    return '<div style="margin-top:20px">' + ''.join(f'<span class="pill">{escape(item)}</span>' for item in items) + '</div>'

def scene(config):
    mode = config.get('mode', '')
    if mode == 'ecosystem':
        return '''<section class="scene-section scene-atlas"><div class="wrap"><div class="scene-header"><span class="eyebrow">Mapa de relações</span><span class="meta">BLACK VOID / ATLAS 01</span></div><div class="atlas-stage"><div class="atlas-orbit orbit-one"></div><div class="atlas-orbit orbit-two"></div><div class="atlas-orbit orbit-three"></div><div class="atlas-center"><span class="meta">01</span><strong>UM<br>NÚCLEO</strong><small>e muitas consequências</small></div><div class="atlas-label atlas-north">INTELIGÊNCIA</div><div class="atlas-label atlas-east">PRODUTO</div><div class="atlas-label atlas-south">CONTINUIDADE</div><div class="atlas-label atlas-west">CONFIANÇA</div></div><p class="scene-foot">Uma operação madura não cresce adicionando ferramentas. Cresce aprendendo a fazer com que elas se escutem.</p></div></section>'''
    if mode == 'product':
        return '''<section class="scene-section scene-console"><div class="wrap"><div class="scene-header"><span class="eyebrow">Kira / interface de decisão</span><span class="meta">LIVE CONTEXT / 02</span></div><div class="console-shell"><div class="console-bar"><span class="console-dot"></span><span>KIRA / WORKSPACE</span><span>MEMORY: ACTIVE</span></div><div class="console-body"><aside><span class="meta">AGENTS</span><strong>03</strong><span class="meta">TASKS IN MOTION</span><strong>12</strong><span class="meta">LAST SIGNAL</span><strong>04:28</strong></aside><div class="console-main"><div class="console-question">Como podemos<br><em>destravar</em> este fluxo?</div><div class="console-line"><span>CONTEXT</span><i></i><span>DECISION</span><i></i><span>ACTION</span></div><div class="console-response">Kira encontrou três pontos de fricção, separou o que pode ser automatizado e deixou a decisão final com quem conhece a consequência.</div></div></div></div><p class="scene-foot">A inteligência começa quando o sistema sabe o suficiente para agir — e o bastante para saber quando parar.</p></div></section>'''
    if mode == 'services':
        return '''<section class="scene-section scene-disciplines"><div class="wrap"><div class="scene-header"><span class="eyebrow">O campo de entrega</span><span class="meta">SIX DISCIPLINES / ONE DEPTH</span></div><div class="discipline-wheel"><div class="wheel-core"><span>PROBLEMA</span><strong>→</strong><span>CAPACIDADE</span></div><div class="wheel-label w1">IA</div><div class="wheel-label w2">SOFTWARE</div><div class="wheel-label w3">AUTOMAÇÃO</div><div class="wheel-label w4">INFRA</div><div class="wheel-label w5">SECURITY</div><div class="wheel-label w6">BRANDING</div></div><p class="scene-foot">O valor não está em escolher uma disciplina. Está em entender qual delas precisa abrir a porta.</p></div></section>'''
    if mode == 'flow':
        return '''<section class="scene-section scene-flow"><div class="wrap"><div class="scene-header"><span class="eyebrow">Antes / depois</span><span class="meta">FLOW STUDY / 03</span></div><div class="flow-rail"><div class="flow-point"><span>01</span><strong>Ruído</strong><p>Mensagens, planilhas e decisões que chegam tarde.</p></div><div class="flow-arrow">→</div><div class="flow-point is-active"><span>02</span><strong>Mapa</strong><p>Contexto suficiente para enxergar onde agir.</p></div><div class="flow-arrow">→</div><div class="flow-point"><span>03</span><strong>Ritmo</strong><p>Um sistema que deixa a equipe pensar de novo.</p></div></div></div></section>'''
    if mode == 'proof':
        return '''<section class="scene-section scene-proof"><div class="wrap"><div class="scene-header"><span class="eyebrow">Como uma decisão fica</span><span class="meta">CASE LOG / 04</span></div><div class="proof-grid"><div class="proof-image"><img src="assets/img/void-fragment.svg" alt="Fragmento de construção com diagrama e superfície vermelha" loading="lazy"><span class="meta">OBJECT / AFTER</span></div><div class="proof-notes"><div class="proof-note"><span>01 / TENSÃO</span><strong>Quando a forma antiga já não comporta o próximo movimento.</strong><p>O problema raramente chega com o nome certo. Antes de construir, a gente escuta o que está tentando acontecer.</p></div><div class="proof-note"><span>02 / DECISÃO</span><strong>Escolher uma estrutura que não precise ser defendida todos os dias.</strong><p>Uma boa decisão reduz o número de explicações necessárias para a operação continuar.</p></div><div class="proof-note"><span>03 / PERMANÊNCIA</span><strong>O resultado é a capacidade de seguir sem pedir permissão.</strong><p>É quando a entrega deixa de parecer entrega e começa a funcionar como parte da casa.</p></div></div></div></div></section>'''
    if mode == 'culture':
        return '''<section class="scene-section scene-culture"><div class="wrap"><div class="scene-header"><span class="eyebrow">O que não aparece no organograma</span><span class="meta">CULTURE / 05</span></div><div class="culture-stage"><img src="assets/img/void-creative-work.webp" alt="Mesa de trabalho com materiais e luz baixa" loading="lazy"><div class="culture-stamp"><span>WE BUILD</span><strong>WITH<br>ATTENTION.</strong><span>NOT WITH NOISE.</span></div></div><div class="culture-columns"><p>Somos uma equipe compacta porque proximidade é parte do método. As melhores decisões acontecem quando a pergunta consegue atravessar o espaço entre quem pensa e quem constrói.</p><p>Não trabalhamos para parecer ocupados. Trabalhamos para deixar algo mais claro, mais forte e mais capaz do que estava quando chegamos.</p></div></div></section>'''
    if mode == 'archive':
        return '''<section class="scene-section scene-archive"><div class="wrap"><div class="scene-header"><span class="eyebrow">Arquivo de continuidade</span><span class="meta">FIELD NOTES / 06</span></div><div class="archive-shelves"><div class="archive-shelf"><span>01</span><strong>PERGUNTAS</strong><em>O que precisa ser verdade?</em></div><div class="archive-shelf"><span>02</span><strong>MAPAS</strong><em>Onde a fricção se esconde?</em></div><div class="archive-shelf"><span>03</span><strong>DECISÕES</strong><em>O que merece continuar?</em></div><div class="archive-shelf"><span>04</span><strong>RITUAIS</strong><em>Como o time segue?</em></div></div></div></section>'''
    return ''

def editorial_page(config):
    content = hero(config['kicker'], config['headline'], config['deck'], config.get('chapter', '01'))
    content += scene(config)
    if config.get('image'):
        content += f'''<section><div class="wrap"><div class="split split--wide"><div><span class="eyebrow reveal">Objeto de estudo</span><p class="lead reveal" style="margin-top:24px">{config.get('image_note', 'Uma superfície feita para ser lida de perto: matéria, sinal e decisão na mesma cena.')}</p></div><div class="feature-art reveal"><img src="{config['image']}" alt="{escape(config.get('image_alt', 'Composição editorial Black Void'))}" loading="lazy"><div><span class="tag">FIG. {config.get('chapter', '01')}</span><h3>{config.get('image_title', 'O sistema por trás da superfície.')}</h3></div></div></div></div></section>'''
    if config.get('quote'):
        content += f'''<section><div class="wrap"><div class="quote reveal"><p>{config['quote']}</p><cite>BLACK VOID / NOTA DE ARQUIVO</cite></div></div></section>'''
    if config.get('items'):
        content += f'''<section><div class="wrap"><div class="section-head"><div><span class="eyebrow">{config.get('items_label', 'Estrutura')}</span><h2 class="h-lg" style="margin-top:18px">{config.get('items_title', 'O que muda quando tudo conversa.')}</h2></div><p class="lead">{config.get('items_intro', 'Cada camada tem uma função. Juntas, elas formam uma operação menos fragmentada.')}</p></div>{chapters(config['items'])}</div></section>'''
    if config.get('cards'):
        cards = ''.join(f'<article class="card reveal" style="--i:{i}"><span class="tag">{label}</span><h3>{title}</h3><p>{desc}</p></article>' for i, (label, title, desc) in enumerate(config['cards']))
        content += f'''<section><div class="wrap"><div class="section-head"><div><span class="eyebrow">Seleção</span><h2 class="h-lg" style="margin-top:18px">{config.get('cards_title', 'Uma operação vista por dentro.')}</h2></div></div><div class="grid-3 reveal-stagger">{cards}</div></div></section>'''
    if config.get('table'):
        rows = ''.join(f'<div class="table-row reveal"><span class="num">{i:02d}</span><strong>{name}</strong><p>{desc}</p><span class="tag">{state}</span></div>' for i, (name, desc, state) in enumerate(config['table'], 1))
        content += f'''<section><div class="wrap"><div class="section-head"><div><span class="eyebrow">Mapa operacional</span><h2 class="h-lg" style="margin-top:18px">{config.get('table_title', 'Camadas que sustentam a entrega.')}</h2></div></div><div class="table-list">{rows}</div></div></section>'''
    content += cta(config.get('cta', 'Abrir uma conversa'))
    return shell(config['title'], config.get('description', config['deck']), content)

def home_page():
    body = '''<section class="home-hero"><div class="home-hero-orbit" aria-hidden="true"><span></span><span></span><span></span></div><div class="wrap"><div class="home-index reveal"><span>00 / ABERTURA</span><span>ARQUIVO VIVO / 2026</span></div><div class="home-hero-art reveal"><img src="pages/assets/img/void-orbit.svg" alt="Artefato orbital preto cortado por uma linha de luz vermelha" /><div class="home-art-caption"><span>FIG. 00</span><span>INTELLIGENCE AS MATERIAL</span></div></div><div class="home-copy"><span class="eyebrow reveal">Black Void / casa de construção</span><h1 class="home-title reveal">A complexidade<br>também pode ser<br><em>bonita.</em></h1><p class="home-deck reveal">Nós construímos o que fica entre uma ideia e sua capacidade de continuar existindo: inteligência, produto, software, infraestrutura, segurança e uma linguagem que faz tudo parecer parte do mesmo organismo.</p><div class="actions reveal"><a class="btn" href="pages/contato.html">Entrar no arquivo <span>↗</span></a><a class="btn ghost" href="pages/ecossistema.html">Ver como se conecta</a></div></div><div class="home-scroll"><span class="home-scroll-line"></span><span>DESLIZE PARA LER</span></div></div></section><div class="marquee"><div class="marquee-track"><span><i>—</i>INTELIGÊNCIA</span><span><i>—</i>SOFTWARE</span><span><i>—</i>INFRAESTRUTURA</span><span><i>—</i>DESIGN</span><span><i>—</i>SEGURANÇA</span><span><i>—</i>PERTENCIMENTO</span><span><i>—</i>INTELIGÊNCIA</span><span><i>—</i>SOFTWARE</span><span><i>—</i>INFRAESTRUTURA</span><span><i>—</i>DESIGN</span><span><i>—</i>SEGURANÇA</span><span><i>—</i>PERTENCIMENTO</span></div></div>'''
    body += '''<section class="manifesto-section"><div class="wrap"><div class="manifesto-grid"><div class="manifesto-aside reveal"><span class="eyebrow">Uma nota antes de começar</span><span class="manifesto-number">01</span><span class="meta">O FUTURO NÃO É UM LUGAR.<br>É UMA FORMA DE OPERAR.</span></div><div class="manifesto-copy reveal"><p class="manifesto-lede">Existem empresas que fazem coisas. E existem lugares que tornam outras coisas possíveis.</p><p>Black Void nasceu para a segunda categoria. Trabalhamos no intervalo onde uma intenção ainda não virou produto, onde uma operação ainda não encontrou seu ritmo, onde o time sabe que pode fazer melhor mas não sabe por onde atravessar.</p><p>O nosso trabalho é entrar sem fazer barulho, encontrar a estrutura escondida e construir uma versão dela que o futuro consiga sustentar.</p><a class="text-link" href="pages/sobre.html">Ler a origem da casa <span>↗</span></a></div></div></div></section>'''
    body += f'''<section class="home-ecosystem"><div class="wrap"><div class="section-head"><div><span class="eyebrow">O organismo</span><h2 class="h-lg">Nada existe<br>sozinho.</h2></div><p class="lead">A Black Void é feita de camadas que se escutam. Quando uma muda, todas as outras ganham uma nova responsabilidade.</p></div><div class="ecosystem-scene"><div class="ecosystem-image reveal"><img src="pages/assets/img/void-signal.svg" alt="Mapa visual de sinais conectando contexto, decisão, sistema e continuidade" loading="lazy"><div class="ecosystem-image-label"><span>FIG. 01</span><span>THE LIVING SYSTEM</span></div></div><div class="ecosystem-core reveal"><div class="core-ring ring-a"></div><div class="core-ring ring-b"></div><div class="core-node"><img src="pages/assets/img/logo.png" alt=""><span>BLACK<br>VOID</span></div><span class="node-label node-top">KIRA / INTELLIGENCE</span><span class="node-label node-right">STUDIO / PRODUCT</span><span class="node-label node-bottom">CLOUD / CONTINUITY</span><span class="node-label node-left">SECURITY / TRUST</span></div></div><div class="ecosystem-footer"><span class="meta">09 MÓDULOS / 01 OPERAÇÃO</span><a class="text-link" href="pages/ecossistema.html">Abrir o ecossistema <span>↗</span></a></div></div></section>'''
    body += '''<section class="home-quote-section"><div class="wrap"><div class="quote quote--large reveal"><p>Não queremos ser<br>a sua agência.<br>Queremos ser o lugar<br>onde a próxima coisa<br><em>se torna possível.</em></p><cite>BLACK VOID / MANIFESTO 00</cite></div></div></section>'''
    body += '''<section class="home-services"><div class="wrap"><div class="section-head"><div><span class="eyebrow">O que construímos</span><h2 class="h-lg">A forma muda.<br>A intenção fica.</h2></div><p class="lead">Seis portas de entrada para a mesma pergunta: o que precisa se tornar mais capaz?</p></div><div class="home-service-list"><a class="home-service reveal" href="pages/ia.html"><span>01</span><strong>Inteligência artificial</strong><em>Dar contexto à máquina.</em><span>↗</span></a><a class="home-service reveal" href="pages/desenvolvimento.html"><span>02</span><strong>Desenvolvimento</strong><em>Dar corpo à intenção.</em><span>↗</span></a><a class="home-service reveal" href="pages/automacao.html"><span>03</span><strong>Automação</strong><em>Dar espaço ao humano.</em><span>↗</span></a><a class="home-service reveal" href="pages/infraestrutura.html"><span>04</span><strong>Infraestrutura</strong><em>Dar continuidade ao que importa.</em><span>↗</span></a><a class="home-service reveal" href="pages/cybersecurity.html"><span>05</span><strong>Cybersecurity</strong><em>Dar confiança ao movimento.</em><span>↗</span></a><a class="home-service reveal" href="pages/branding.html"><span>06</span><strong>Branding</strong><em>Dar uma forma que permaneça.</em><span>↗</span></a></div></div></section>'''
