    body += '''<section class="home-final"><div class="wrap"><span class="eyebrow">Última nota</span><h2 class="home-final-title reveal">O que você<br>quer tornar<br><em>possível?</em></h2><p class="lead reveal">Você não precisa trazer uma resposta pronta. Só precisa trazer a pergunta que não deixa você em paz.</p><a class="btn reveal" href="pages/contato.html">Abrir uma conversa <span>↗</span></a><span class="home-final-mark">BV / 00—∞</span></div></section>'''
    return root_shell('Black Void', 'A Black Void constrói inteligência, produto, software, infraestrutura e sistemas que tornam o futuro operável.', body)

