MEDIA_BY_SLUG = {
    'casos': CASE, 'carreira': CULTURE, 'blog': CASE, 'recursos': ECOSYSTEM, 'faq': CULTURE,
    'planos': HERO, 'tecnologias': ECOSYSTEM, 'cybersecurity': URBAN, 'automacao': CASE,
    'documentacao': ECOSYSTEM, 'Starter': HERO,
}
SCENE_BY_SLUG = {
    'ecossistema': 'ecosystem', 'kira': 'product', 'servicos': 'services',
    'ia': 'flow', 'automacao': 'flow', 'desenvolvimento': 'flow',
    'infraestrutura': 'flow', 'cybersecurity': 'flow', 'branding': 'flow',
    'portfolio': 'proof', 'casos': 'proof', 'sobre': 'culture', 'team': 'culture',
    'carreira': 'culture', 'blog': 'culture', 'recursos': 'archive', 'faq': 'archive',
    'planos': 'archive', 'tecnologias': 'archive', 'documentacao': 'archive', 'Starter': 'archive',
}
for slug, config in COMMON.items():
    if slug in SCENE_BY_SLUG:
        config['mode'] = SCENE_BY_SLUG[slug]
    if not config.get('image') and slug in MEDIA_BY_SLUG:
        config['image'] = MEDIA_BY_SLUG[slug]
        config['image_alt'] = f'Imagem editorial da página {config["title"]}'
        config['image_title'] = config.get('image_title', f'{config["title"]} como matéria.')
        config['image_note'] = config.get('image_note', 'Uma camada visual para tornar a ideia mais próxima, concreta e memorável.')
    (PAGES / f'{slug}.html').write_text(editorial_page(config), encoding='utf-8')

(ROOT / 'index.html').write_text(home_page(), encoding='utf-8')

def contact_page():
    body = hero('Contato', 'Dê um nome<br>ao próximo <em style="color:var(--void-red);font-style:normal">movimento.</em>', 'Conte o que está difícil, o que já tentou e o que precisa ser verdade depois da primeira entrega.', '22')
    body += '''<section><div class="wrap"><div class="split"><div><span class="eyebrow">Briefing aberto</span><p class="lead" style="margin-top:24px">Não precisa chegar com um escopo fechado. Uma boa pergunta já é material suficiente para começar.</p><p class="meta" style="margin-top:30px;color:var(--muted)">Resposta inicial em até dois dias úteis / contato@blackvoid.studio</p></div><form class="card" action="mailto:contato@blackvoid.studio" method="post" enctype="text/plain"><label class="meta" for="name">Seu nome</label><input id="name" name="nome" required placeholder="Como podemos chamar você?"><label class="meta" for="email">E-mail</label><input id="email" name="email" type="email" required placeholder="voce@empresa.com"><label class="meta" for="message">O que precisa mudar?</label><textarea id="message" name="mensagem" rows="6" required placeholder="Conte o problema, o contexto e o que seria uma boa primeira decisão."></textarea><button class="btn" type="submit">Enviar briefing ↗</button></form></div></div></section>'''
    return shell('Contato', 'Abra uma conversa com a Black Void sobre IA, software, infraestrutura ou design.', body + cta('Voltar ao início'))

(PAGES / 'contato.html').write_text(contact_page(), encoding='utf-8')

def systems_page():
    body = hero('Arquivo operacional', 'Sistemas que<br>continuam depois<br>da <em style="color:var(--void-red);font-style:normal">apresentação.</em>', 'Algumas ideias precisam de uma superfície para operar. Este é o mapa dos sistemas que a Black Void está construindo, testando e preparando para ganhar continuidade.', '22')
    body += '''<section class="scene-section scene-archive"><div class="wrap"><div class="scene-header"><span class="eyebrow">Mapa de continuidade</span><span class="meta">SYSTEMS / 2026</span></div><div class="archive-shelves"><div class="archive-shelf"><span>01</span><strong>SINAL</strong><em>O que mudou?</em></div><div class="archive-shelf"><span>02</span><strong>DECISÃO</strong><em>O que merece prioridade?</em></div><div class="archive-shelf"><span>03</span><strong>OPERAÇÃO</strong><em>Como o time segue?</em></div><div class="archive-shelf"><span>04</span><strong>PROVA</strong><em>O que continua de pé?</em></div></div></div></section>'''
    body += '''<section><div class="wrap"><div class="section-head"><div><span class="eyebrow">Entradas do arquivo</span><h2 class="h-lg" style="margin-top:18px">Não é uma vitrine.<br>É um mapa de estado.</h2></div><p class="lead">Cada entrada informa o que o sistema faz, em que ambiente existe e qual é o próximo limite antes de ser compartilhado.</p></div><div class="grid-2 reveal-stagger"><article class="card reveal"><span class="tag">ATLAS COMMAND / 2026</span><h3>Uma superfície de decisão.</h3><p>Prioridades autenticadas, contexto e eventos para transformar sinais dispersos em ações que podem ser acompanhadas.</p><div style="margin-top:20px"><span class="pill">PRÉVIA</span><span class="pill">ACESSO RESTRITO</span></div><a class="text-link" href="https://atlas-command-nine.vercel.app" style="margin-top:22px">Abrir prévia ↗</a></article><article class="card reveal"><span class="tag">TMS / 2026</span><h3>Operação logística em camadas.</h3><p>Tracker, painel administrativo e portal do cliente separados por responsabilidade, acesso e consequência.</p><div style="margin-top:20px"><span class="pill">STAGING</span><span class="pill">PAINÉIS SEPARADOS</span></div><a class="text-link" href="https://tms-painel-adm.vercel.app" style="margin-top:22px">Abrir painel administrativo ↗</a><a class="text-link" href="https://tms-painel-client.vercel.app" style="margin-top:12px">Abrir portal do cliente ↗</a></article><article class="card reveal"><span class="tag">TRACKERTMS / DISTRIBUIÇÃO</span><h3>Um ponto de entrada para o dispositivo.</h3><p>Site estático para distribuir o APK assinado do Tracker, sem armazenar chaves de assinatura na interface.</p><div style="margin-top:20px"><span class="pill">DOWNLOAD</span><span class="pill">RELEASE ASSINADO</span></div><a class="text-link" href="https://tms-downloads.vercel.app" style="margin-top:22px">Abrir distribuição ↗</a></article><article class="card reveal"><span class="tag">LABORATÓRIO / DEMO</span><h3>O que ainda está aprendendo.</h3><p>Backends de demonstração são úteis para contar uma história, mas não devem ser confundidos com operação multi-tenant ou produção.</p><div style="margin-top:20px"><span class="pill">SOMENTE DEMO</span><span class="pill">NÃO PROMOVER</span></div></article></div></div></section>'''
    body += '''<section><div class="wrap"><div class="section-head"><div><span class="eyebrow">Critério de publicação</span><h2 class="h-lg" style="margin-top:18px">Compartilhar também<br>é saber <em style="color:var(--void-red);font-style:normal">limitar.</em></h2></div><p class="lead">O catálogo não expõe tokens, bancos, dados de clientes, endpoints de recuperação ou ações administrativas. Ele aponta para superfícies com o nível de acesso explicitado.</p></div><div class="table-list"><div class="table-row reveal"><span class="num">01</span><strong>Privado</strong><p>Autenticação e validação do titular ainda são necessárias.</p><span class="tag">ATLAS</span></div><div class="table-row reveal"><span class="num">02</span><strong>Staging</strong><p>Backend, CORS, login, isolamento e healthcheck devem ser confirmados.</p><span class="tag">TMS</span></div><div class="table-row reveal"><span class="num">03</span><strong>Distribuição</strong><p>Somente releases HTTPS assinados e configurados.</p><span class="tag">TRACKER</span></div></div></div></section>'''
    body += cta('Voltar ao portfólio')
    return shell('Sistemas', 'Atlas Command, TMS e sistemas em operação da Black Void Studio.', body)

