def docs_page(slug, title, kicker, headline, intro, entries):
    body = hero(kicker, headline, intro, 'DOC')
    rows = ''.join(f'<article class="chapter reveal"><span class="chapter-index">{i:02d} / DOC</span><div><h3>{name}</h3><p>{desc}</p><a class="btn ghost" href="{href}" style="margin-top:22px">Abrir página ↗</a></div></article>' for i, (name, desc, href) in enumerate(entries, 1))
    body += f'''<section><div class="wrap"><div class="section-head"><div><span class="eyebrow">{kicker}</span><h2 class="h-lg" style="margin-top:18px">Leia pelo<br>ponto certo.</h2></div><p class="lead">A documentação também é parte da experiência: clara para começar, precisa para continuar.</p></div><div>{rows}</div></div></section>'''
    return f'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} — Black Void</title><link rel="icon" href="../pages/assets/img/logo.png"><link rel="stylesheet" href="../pages/assets/css/style.css"></head><body><div id="loader"><img class="ldr-mark" src="../pages/assets/img/logo.png" alt=""><div class="ldr-word">BLACK VOID / DOCS</div><div class="ldr-bar"><i></i></div></div><div data-include="../components/menu-superior.html"></div><main>{body}</main><footer><div data-include="../components/menu.html"></div></footer><script src="../components/include.js"></script><script src="../pages/assets/js/main.js"></script></body></html>'''

